-- Gold table facilities.DimDataSource (dimension, SCD type 1).
-- Generated by `python -m fde render` from models/gold/facilities/DimDataSource.yml. Do not edit: change the spec and render again.

IF SCHEMA_ID('facilities') IS NULL
    EXEC('CREATE SCHEMA [facilities]');
GO

IF OBJECT_ID('facilities.DimDataSource') IS NULL
CREATE TABLE [facilities].[DimDataSource] (
    [DimDataSource_SK]     bigint NOT NULL,
    [DataSource_BK]        varchar(20) NOT NULL,
    [SourceName]           varchar(500) NULL,
    [SourceUrl]            varchar(1000) NULL,
    [InsertLoadStepID]     varchar(36) NOT NULL,
    [InsertTimestamp]      datetime2(6) NOT NULL,
    [LastUpdateLoadStepID] varchar(36) NOT NULL,
    [LastUpdateTimestamp]  datetime2(6) NOT NULL
);
GO

-- Columns added to the spec after the first deploy.
-- Fabric can only add nullable columns; type changes need a
-- migration (see the standards, section 7.5).
IF NOT EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS
               WHERE TABLE_SCHEMA = 'facilities'
               AND TABLE_NAME = 'DimDataSource'
               AND COLUMN_NAME = 'SourceName')
    ALTER TABLE [facilities].[DimDataSource] ADD [SourceName] varchar(500) NULL;
IF NOT EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS
               WHERE TABLE_SCHEMA = 'facilities'
               AND TABLE_NAME = 'DimDataSource'
               AND COLUMN_NAME = 'SourceUrl')
    ALTER TABLE [facilities].[DimDataSource] ADD [SourceUrl] varchar(1000) NULL;
GO

-- Informational key (Fabric does not enforce it; the tests do).
IF NOT EXISTS (SELECT 1 FROM sys.key_constraints
               WHERE name = 'PK_DimDataSource')
    ALTER TABLE [facilities].[DimDataSource] ADD CONSTRAINT [PK_DimDataSource]
        PRIMARY KEY NONCLUSTERED ([DimDataSource_SK]) NOT ENFORCED;
GO

-- Unknown member: facts point here when a key has no dimension row.
IF NOT EXISTS (SELECT 1 FROM [facilities].[DimDataSource] WHERE [DimDataSource_SK] = -1)
    INSERT INTO [facilities].[DimDataSource]
        ([DimDataSource_SK], [DataSource_BK], [InsertLoadStepID], [InsertTimestamp], [LastUpdateLoadStepID], [LastUpdateTimestamp])
    VALUES (-1, '-1', 'deploy', SYSUTCDATETIME(), 'deploy', SYSUTCDATETIME());
GO
